import{_ as i,o as t,c as a,a0 as r}from"./chunks/framework.DqMqoJl9.js";const c=JSON.parse('{"title":"设计原则","description":"","frontmatter":{},"headers":[],"relativePath":"designPattern/3-principles.md","filePath":"designPattern/3-principles.md","lastUpdated":1791573371000}'),e={name:"designPattern/3-principles.md"};function o(n,l,s,p,d,u){return t(),a("div",null,[...l[0]||(l[0]=[r('<h1 id="设计原则" tabindex="-1">设计原则 <a class="header-anchor" href="#设计原则" aria-label="Permalink to &quot;设计原则&quot;">​</a></h1><h2 id="_1-什么是设计" tabindex="-1">1 什么是设计 <a class="header-anchor" href="#_1-什么是设计" aria-label="Permalink to &quot;1 什么是设计&quot;">​</a></h2><p>todo</p><p>UNIX/LINUX 的设计准则</p><h2 id="_2-五大设计原则-solid" tabindex="-1">2 五大设计原则 SOLID <a class="header-anchor" href="#_2-五大设计原则-solid" aria-label="Permalink to &quot;2 五大设计原则 SOLID&quot;">​</a></h2><ol><li>S 单一职责原则</li><li>O 开放封闭原则</li><li>L 李氏置换原则</li><li>I 接口独立原则</li><li>D 依赖导致原则</li></ol><p><strong>S 单一职责原则：</strong></p><ul><li>一个程序只做一件事</li><li>如果功能过于复杂就拆分开，每个部分保持独立</li></ul><p><strong>O 开放封闭原则：</strong></p><ul><li>对扩展开发，对修改封闭</li><li>增加需求时，扩展新代码，而非修改已有代码</li></ul><p><strong>L 李氏置换原则：</strong></p><ul><li>子类能够覆盖父类</li><li>父类能出现的地方 子类就能出现</li></ul><p><strong>I 接口独立原则：</strong></p><ul><li>保持接口的单一独立</li><li>JS 中没有接口，使用较少</li><li>类似于单一职责原则，这里更关注接口</li></ul><p><strong>D 依赖倒置原则：</strong></p><ul><li>面向接口编程，依赖于抽象而不依赖具体 (只关注功能不关注具体实现)</li><li>使用方法只关注接口而不关注具体类的实现</li><li>JS 中使用较少 (没有接口 &amp; 弱类型)</li></ul><h2 id="_3-23-种设计模式" tabindex="-1">3 23 种设计模式 <a class="header-anchor" href="#_3-23-种设计模式" aria-label="Permalink to &quot;3 23 种设计模式&quot;">​</a></h2><p><strong>创建型：</strong></p><ul><li>工厂模式 (工厂方法模式、抽象工厂模式、建造者模式)</li><li>单例模式</li><li>原型模式</li></ul><p><strong>结构型：</strong></p><ul><li>适配器模式</li><li>装饰器模式</li><li>代理模式</li><li>外观模式</li><li>桥接模式</li><li>组合模式</li><li>享元模式</li></ul><p><strong>行为型 1:</strong></p><ul><li>策略模式</li><li>模板方法模式</li><li>观察者模式</li><li>迭代器模式</li><li>职责连模式</li><li>命令模式</li></ul><p><strong>行为型 2:</strong></p><ul><li>备忘录模式</li><li>状态模式</li><li>访问者模式</li><li>中介者模式</li><li>解释器模式</li></ul>',25)])])}const g=i(e,[["render",o]]);export{c as __pageData,g as default};
